import type { BlogSectie } from "./blog";
export type BlogTranslation={title:string;excerpt:string;photo:string;sections:BlogSectie[];questions?:{v:string;a:string}[]};
export const BLOG_TRANSLATIONS:Record<string,{en:BlogTranslation;de:BlogTranslation}>={
 "verse-vis-bewaren-en-bereiden-tips": {
 en:{title:"Storing and preparing fresh fish: tips from the fishmonger",excerpt:"Fresh fish needs careful handling. Practical advice on transport, refrigeration, freezing and cooking your purchase.",photo:"Fresh cod fillet to keep chilled and cook",sections:[{alineas:["Fresh fish needs careful transport, refrigeration and preparation. Always follow the storage advice given at purchase and the information on the packaging."]},{kop:"Freshness and safety are different",alineas:["Smell and appearance help assess quality but do not prove fish is safe.","If fish smells unpleasant or you are unsure how it was stored, do not eat it; ask for advice."]},{kop:"Refrigerating fish",alineas:["Transport fish in a cool bag and refrigerate it promptly at 4°C in a covered container. Preferably eat unpackaged fresh fish on the day of purchase.","Respect the use-by date. Keep raw fish separate from ready-to-eat food; harmful bacteria are not always visible or detectable by smell."]},{kop:"Freezing and thawing",alineas:["Ask whether the product is suitable for home freezing and whether it has already been thawed. Wrap securely and follow the product’s advice.","Thaw covered in the fridge, not on the worktop. Previous freezing alone does not establish suitability for eating raw."]},{kop:"Check that fish is cooked through",alineas:["Use clean utensils and prevent cross-contamination. Cook raw fish thoroughly; time alone does not prove it is done.","The time needed depends on thickness and cooking method. Ask us for advice for your fillet."]},{kop:"Extra care for vulnerable groups",alineas:["Pregnant people, young children, older people and those with weakened immunity should avoid raw fish and smoked fish that has not been thoroughly heated. Separate advice on fish species also applies during pregnancy.","Read the Dutch Nutrition Centre’s guidance or discuss personal questions with a qualified health professional."]}]},
 de:{title:"Frischen Fisch lagern und zubereiten: Tipps vom Fischhändler",excerpt:"Frischer Fisch braucht sorgfältigen Umgang. Praktische Tipps zu Transport, Kühlung, Einfrieren und Zubereitung Ihres Einkaufs.",photo:"Frisches Kabeljaufilet zum gekühlten Lagern und Zubereiten",sections:[{alineas:["Frischer Fisch braucht sorgfältigen Transport, Kühlung und Zubereitung. Beachten Sie immer die beim Kauf erhaltenen Lagerhinweise und die Verpackungsinformationen."]},{kop:"Frische und Sicherheit sind verschieden",alineas:["Geruch und Aussehen helfen bei der Qualitätsbeurteilung, beweisen aber nicht, dass Fisch sicher ist.","Riecht der Fisch unangenehm oder sind Sie unsicher über die Lagerung? Essen Sie ihn nicht und fragen Sie nach Rat."]},{kop:"Fisch im Kühlschrank lagern",alineas:["Fisch in einer Kühltasche transportieren und zu Hause sofort abgedeckt bei 4°C kühlen. Unverpackten frischen Fisch möglichst am Kauftag essen.","Das Verbrauchsdatum beachten. Rohen Fisch von verzehrfertigen Speisen trennen; krankmachende Bakterien sind nicht immer sichtbar oder zu riechen."]},{kop:"Einfrieren und Auftauen",alineas:["Fragen Sie, ob sich das Produkt zum Einfrieren zu Hause eignet und ob es bereits aufgetaut wurde. Gut verpacken und den Produkthinweisen folgen.","Abgedeckt im Kühlschrank auftauen, nicht auf der Arbeitsplatte. Früheres Einfrieren allein beweist keine Eignung für rohen Verzehr."]},{kop:"Garheit prüfen",alineas:["Sauberes Küchenzubehör verwenden und Kreuzkontamination vermeiden. Rohen Fisch vollständig durchgaren; die Zeit allein beweist keine Garheit.","Die nötige Zeit hängt von Dicke und Zubereitung ab. Fragen Sie uns nach Rat für Ihr Filet."]},{kop:"Besondere Vorsicht für gefährdete Gruppen",alineas:["Schwangere, kleine Kinder, ältere Menschen und Menschen mit geschwächtem Immunsystem sollten rohen und nicht vollständig erhitzten Räucherfisch meiden. Für Schwangere gelten zusätzlich eigene Empfehlungen zu Fischarten.","Lesen Sie die Hinweise des niederländischen Ernährungszentrums oder besprechen Sie persönliche Fragen mit einer qualifizierten Gesundheitsfachkraft."]}]}
 },
 "echt-gerookte-vis-vs-kunstmatige-rooksmaak": {
 en:{title:"Smoked fish and smoke flavouring: what is the difference?",excerpt:"Smoking and added smoke flavouring are different preparation methods. Read the label and ask how your product was made.",photo:"Smoked salmon rolls with cream cheese",sections:[{alineas:["Smoked salmon, mackerel and herring each have their own taste and texture. Production methods vary by product. The label and supplier information are more useful than colour or price alone."]},{kop:"Cold and hot smoking",alineas:["Cold smoking exposes fish to smoke without thoroughly cooking it as frying or boiling would. Hot smoking uses more heat and can also cook the fish.","The exact process and storage requirements belong to the particular product. Do not assume every smoked fish is already fully cooked."]},{kop:"Added smoke flavouring",alineas:["Smoke flavouring is added as an ingredient to give a smoky taste. That is a different production method from exposing the product to smoke.","The ingredients list may identify smoke flavouring. A different taste or price alone does not prove how a product was made; ask if anything is unclear."]},{kop:"How to find out",alineas:["Read the ingredients, label and storage advice. Traditionally smoked products can also contain other ingredients; ‘only fish, salt and smoke’ is not a general rule.","Ask your fishmonger about the supplier and production method. Origin, smoking and certification are separate questions."]},{kop:"Smoked fish at Schaap’s",alineas:["Our range includes smoked salmon and mackerel. Ask at the counter about current product information and available varieties.","Choose fish that suits your salad, sandwich or recipe. Keep smoked fish chilled and follow storage advice. Vulnerable groups should take extra care with smoked fish that has not been thoroughly heated."]}]},
 de:{title:"Räucherfisch und Raucharoma: was ist der Unterschied?",excerpt:"Räuchern und zugesetztes Raucharoma sind verschiedene Herstellungsverfahren. Lesen Sie das Etikett und fragen Sie nach der Herstellung.",photo:"Räucherlachsröllchen mit Frischkäse",sections:[{alineas:["Räucherlachs, Makrele und Bückling haben jeweils eigenen Geschmack und Struktur. Die Herstellung variiert nach Produkt. Etikett und Lieferanteninformationen helfen mehr als Farbe oder Preis allein."]},{kop:"Kalt- und Heißräuchern",alineas:["Beim Kalträuchern wird der Fisch geräuchert, ohne ihn wie beim Kochen oder Braten vollständig durchzugaren. Heißräuchern verwendet mehr Wärme und kann den Fisch zugleich garen.","Das genaue Verfahren und die Haltbarkeit gehören zum konkreten Produkt. Gehen Sie nicht davon aus, dass jeder Räucherfisch bereits vollständig gegart ist."]},{kop:"Zugesetztes Raucharoma",alineas:["Raucharoma wird als Zutat verwendet, um Rauchgeschmack hinzuzufügen. Das ist ein anderes Verfahren, als das Produkt Rauch auszusetzen.","Die Zutatenliste kann Raucharoma nennen. Ein anderer Geschmack oder Preis allein beweist nicht, wie ein Produkt hergestellt wurde; fragen Sie bei Unklarheit nach."]},{kop:"So bekommen Sie Klarheit",alineas:["Lesen Sie Zutaten, Etikett und Lagerhinweise. Auch traditionell geräucherte Produkte können weitere Zutaten enthalten; ‚nur Fisch, Salz und Rauch‘ ist keine allgemeine Regel.","Fragen Sie Ihren Fischhändler nach Lieferant und Herstellungsverfahren. Herkunft, Räuchern und Zertifizierung sind getrennte Fragen."]},{kop:"Räucherfisch bei Schaap’s",alineas:["Unser Sortiment umfasst unter anderem Räucherlachs und Makrele. Fragen Sie an der Theke nach aktuellen Produktinformationen und verfügbaren Varianten.","Wählen Sie Fisch passend zu Salat, Brot oder Rezept. Räucherfisch gekühlt halten und Lagerhinweise beachten. Gefährdete Personengruppen müssen bei nicht vollständig erhitztem Räucherfisch besonders vorsichtig sein."]}]}
 },
 "kibbeling-vs-lekkerbek-het-verschil": {
 en:{title:"Kibbeling or lekkerbek: what is the difference?",excerpt:"Both are golden fried fish, but kibbeling and lekkerbek are different. A short guide from the fish counter.",photo:"Crisp kibbeling with sauce",sections:[{alineas:["Customers regularly ask about the difference between kibbeling and lekkerbek. Here is what you get and how to choose."]},{kop:"Kibbeling: small pieces",alineas:["Kibbeling consists of pieces of white fish in batter, fried until golden. Cod is a traditional choice, but the fish used can vary by product and supply. Ask which fish we are using that day; pollack and saithe are also different species."]},{kop:"Lekkerbek: a whole hake fillet",alineas:["Our lekkerbek is a hake fillet in batter, fried until golden. You get a whole fillet rather than the small pieces used for kibbeling."]},{kop:"Which should you choose?",alineas:["Kibbeling is easy to share and goes well with ravigote sauce. Lekkerbek suits a roll or a meal. Nutritional values vary with fish, batter and portion; our product figures are indicative.","Coming for a larger quantity on a busy day? Ask about options beforehand on WhatsApp. Your message is not a confirmed order or a guarantee something will be ready."]}]},
 de:{title:"Kibbeling oder Lekkerbek: was ist der Unterschied?",excerpt:"Beides ist goldbrauner Backfisch, aber Kibbeling und Lekkerbek unterscheiden sich. Eine kurze Erklärung von der Fischtheke.",photo:"Knusprige Kibbeling mit Sauce",sections:[{alineas:["An der Theke werden wir regelmäßig nach dem Unterschied zwischen Kibbeling und Lekkerbek gefragt. Hier erklären wir, was Sie bekommen und wie Sie wählen können."]},{kop:"Kibbeling: kleine Stücke",alineas:["Kibbeling bestehen aus Weißfischstücken im Backteig, goldbraun frittiert. Kabeljau ist eine traditionelle Wahl, doch der verwendete Fisch kann je nach Produkt und Angebot variieren. Fragen Sie, welchen Fisch wir an diesem Tag verwenden; Pollack und Köhler sind außerdem verschiedene Arten."]},{kop:"Lekkerbek: ein ganzes Seehechtfilet",alineas:["Unser Lekkerbek ist ein Seehechtfilet im Backteig, goldbraun frittiert. Sie bekommen ein ganzes Filet statt der kleinen Stücke von Kibbeling."]},{kop:"Was wählen Sie?",alineas:["Kibbeling lassen sich gut teilen und passen zu Ravigotesauce. Lekkerbek eignet sich im Brötchen oder als Teil einer Mahlzeit. Nährwerte variieren nach Fisch, Teig und Portion; unsere Produktangaben sind Richtwerte.","Möchten Sie an einem vollen Tag eine größere Menge holen? Fragen Sie vorher per WhatsApp nach den Möglichkeiten. Ihre Nachricht ist keine bestätigte Bestellung und garantiert nicht, dass etwas bereitsteht."]}]}
 },
 "de-echte-hollandse-garnaal": {
 en:{title:"Dutch brown shrimp: small, delicate and full of flavour",excerpt:"Dutch brown shrimp are small with a sweet, briny flavour. Discover how they differ from large prawns, how they are prepared and what MSC means.",photo:"Dutch brown shrimp",sections:[{alineas:["Dutch brown shrimp, Crangon crangon, are not the same species as large tropical prawns. They are small and grey-brown in the water, changing colour when cooked. Their sweet, briny flavour suits toast, a cocktail or a simple salad."]},{kop:"From catch to your plate",alineas:["Origin and processing relate to the particular delivery. Ask us about the supplier, catch area and how the offered shrimp have been peeled.","Our recipes use peeled, already-cooked shrimp. Keep them chilled and add shortly before serving; prolonged cooking harms their texture."]},{kop:"MSC certification",alineas:["We offer MSC-certified Dutch brown shrimp. MSC concerns sustainable wild catch and traceability; it is not an organic label. Check the information for the specific product at purchase.","Ask about current availability on WhatsApp if you need shrimp for a particular dish or a larger quantity. We are happy to discuss the options."]}]},
 de:{title:"Nordseegarnelen: klein, fein und voller Geschmack",excerpt:"Nordseegarnelen sind klein und schmecken süßlich und salzig. Lesen Sie über den Unterschied zu großen Garnelen, Verarbeitung und MSC-Zertifizierung.",photo:"Nordseegarnelen",sections:[{alineas:["Die Nordseegarnele, Crangon crangon, ist nicht dieselbe Art wie eine große tropische Garnele. Sie ist klein und im Wasser graubraun; beim Kochen ändert sie ihre Farbe. Der süßlich-salzige Geschmack passt zu Toast, Cocktail oder einem einfachen Salat."]},{kop:"Vom Fang auf Ihren Teller",alineas:["Herkunft und Verarbeitung gehören zur konkreten Lieferung. Fragen Sie uns nach Lieferant, Fanggebiet und der Art, wie die angebotenen Garnelen geschält wurden.","Unsere Rezepte verwenden geschälte, bereits gekochte Garnelen. Gekühlt halten und kurz vor dem Servieren hinzufügen; langes Mitkochen schadet der Struktur."]},{kop:"MSC-zertifiziert",alineas:["Wir bieten MSC-zertifizierte Nordseegarnelen an. MSC steht für nachhaltigen Wildfang und Rückverfolgbarkeit, nicht für Bio. Prüfen Sie beim Kauf die Informationen des konkreten Produkts.","Fragen Sie per WhatsApp nach der aktuellen Verfügbarkeit, wenn Sie Garnelen für ein bestimmtes Gericht oder größere Mengen möchten. Wir besprechen gern die Möglichkeiten."]}]}
 },
 "marktdag-in-leiden-achter-de-kraam": {
 en:{title:"Market day in Leiden: behind the fish stall",excerpt:"We visit Leiden’s market every Wednesday and Saturday. Here is what goes into preparing the stall and helping customers choose their fish.",photo:"Herring roll with chopped onion, a familiar market favourite",sections:[{alineas:["Leiden’s market has been our second home for years. We set up our stall every Wednesday and Saturday. Behind a herring roll or a portion of kibbeling is a morning of preparation."]},{kop:"Before the first customers",alineas:["On market days, fish must be loaded, ice prepared and frying oil brought to temperature. Then we arrange the counter so customers can choose their fish and ask questions."]},{kop:"Why the market is different from the shop",alineas:["At the market, things move faster and feel more direct. You see the fish, smell fried kibbeling and hear conversations at the stall. For many customers, visiting is part of their weekly shopping.","Want to collect a seafood platter at the market? Agree the location, date and time beforehand and obtain confirmation. A message does not automatically mean everything is ready or that there will be no wait."]},{kop:"Three places, one quality",alineas:["Our Herenstraat shop opens Tuesday to Saturday. We visit Leiden’s market on Wednesdays and Saturdays, and Hoogvliet in Voorschoten on Fridays. See the locations page for times and directions; Wednesday’s landmark is different from Saturday’s."]}]},
 de:{title:"Markttag in Leiden: ein Blick hinter den Stand",excerpt:"Jeden Mittwoch und Samstag sind wir auf dem Leidener Markt. Was zur Vorbereitung des Stands gehört und wie wir bei der Fischwahl helfen.",photo:"Matjesbrötchen mit Zwiebeln, ein vertrauter Marktklassiker",sections:[{alineas:["Der Leidener Markt ist seit Jahren unser zweites Zuhause. Jeden Mittwoch und Samstag bauen wir unseren Stand auf. Hinter einem Matjesbrötchen oder einer Portion Kibbeling steckt ein Morgen voller Vorbereitung."]},{kop:"Vor den ersten Kunden",alineas:["An Markttagen muss Fisch geladen, Eis vorbereitet und das Frittieröl erhitzt werden. Danach richten wir die Theke ein, damit Kunden ihren Fisch auswählen und Fragen stellen können."]},{kop:"Warum der Markt anders ist als das Geschäft",alineas:["Am Markt geht es schneller und direkter zu. Sie sehen den Fisch, riechen die frittierten Kibbeling und hören die Gespräche am Stand. Für viele Kunden gehört der Besuch zum wöchentlichen Einkauf.","Möchten Sie eine Fischplatte am Markt abholen? Vereinbaren Sie Standort, Datum und Zeit vorher mit uns und lassen Sie es bestätigen. Eine Nachricht bedeutet nicht automatisch, dass alles bereitsteht oder keine Wartezeit entsteht."]},{kop:"Drei Orte, eine Qualität",alineas:["Unser Geschäft an der Herenstraat öffnet von Dienstag bis Samstag. Mittwochs und samstags stehen wir auf dem Leidener Markt, freitags bei Hoogvliet in Voorschoten. Auf der Standortseite finden Sie Zeiten und Anfahrt; der Orientierungspunkt am Mittwoch ist ein anderer als am Samstag."]}]}
 },
 "waar-koop-je-biologische-vis-in-leiden": {
 en:{title:"Organic fish in Leiden: what should you look for?",excerpt:"Looking for organic fish? Check the product’s certification, ask about origin and discuss current availability with your fishmonger.",photo:"Serving suggestion: salmon in a fresh salad",sections:[{kop:"Look at the product, not just the story",alineas:["Organic farming, ASC and MSC are different designations. A sustainable story about a farmer does not itself prove a particular fillet is certified organic. Ask for the information belonging to that product."]},{kop:"Our VÅRLAKS salmon",alineas:["At Schaap’s Vishandel we sell VÅRLAKS salmon. The supplier describes northern Norwegian origins, family businesses and traceability. Ask us about the current origin and certification of the delivery at our counter."]},{kop:"Ask about current availability",alineas:["Visit Herenstraat 48 in Leiden, Tuesday to Saturday, or send a WhatsApp message beforehand. Tell us which fish you want and whether organic certification is important to you. We will discuss what we can offer. Only seafood platters can be ordered online."]}]},
 de:{title:"Bio-Fisch in Leiden: worauf sollten Sie achten?",excerpt:"Sie suchen Bio-Fisch? Prüfen Sie das Siegel des Produkts, fragen Sie nach der Herkunft und besprechen Sie die aktuelle Verfügbarkeit mit Ihrem Fischhändler.",photo:"Serviervorschlag: Lachs in einem frischen Salat",sections:[{kop:"Auf das Produkt achten, nicht nur auf die Geschichte",alineas:["Bio-Zucht, ASC und MSC sind unterschiedliche Kennzeichnungen. Eine nachhaltige Geschichte über einen Züchter beweist allein nicht, dass ein bestimmtes Filet bio-zertifiziert ist. Fragen Sie nach den Informationen, die zu diesem Produkt gehören."]},{kop:"Unser VÅRLAKS-Lachs",alineas:["Bei Schaap’s Vishandel verkaufen wir VÅRLAKS-Lachs. Der Lieferant beschreibt Herkunft aus Nordnorwegen, Familienbetriebe und Rückverfolgbarkeit. Fragen Sie uns nach der aktuellen Herkunft und Zertifizierung der Lieferung an unserer Theke."]},{kop:"Aktuelle Verfügbarkeit erfragen",alineas:["Besuchen Sie uns an der Herenstraat 48 in Leiden von Dienstag bis Samstag oder schreiben Sie vorher per WhatsApp. Nennen Sie den gewünschten Fisch und ob Ihnen eine Bio-Zertifizierung wichtig ist. Wir besprechen gern unser Angebot. Nur Fischplatten können online bestellt werden."]}]}
 },
 "wat-betekenen-msc-asc-en-het-eu-bio-logo": {
 en:{title:"Organic, ASC and MSC: what do fish labels mean?",excerpt:"Organic production, responsible farming and sustainable wild catch are not the same. Learn to read the labels on your fish.",photo:"Organic, ASC and MSC explained: organic farming, responsible farming and sustainable wild catch",sections:[{kop:"Three designations, different questions",alineas:["Are you looking for organic fish, responsibly farmed fish or sustainable wild catch? These are different requirements. Check which label actually belongs to the chosen product and ask for an explanation if it is unclear."]},{kop:"Organic farming",alineas:["Organic means certified farming under organic rules. An origin story or supplier’s name does not replace that certification. Ask which organic products are currently available."]},{kop:"ASC and MSC",alineas:["ASC concerns responsible aquaculture; MSC concerns sustainable wild catch and supply-chain traceability. ASC is not the same as organic certification. MSC is not an organic label either."]},{kop:"How we help you choose",alineas:["At our counter or on WhatsApp, we discuss origin, availability and the information for the specific product. Our organic fish page sets out the differences clearly."]}]},
 de:{title:"Bio, ASC und MSC: was bedeuten die Fischsiegel?",excerpt:"Bio, verantwortungsvolle Zucht und nachhaltiger Wildfang sind nicht dasselbe. So lesen Sie die Kennzeichnungen Ihres Fischs.",photo:"Bio, ASC und MSC erklärt: Bio-Zucht, verantwortungsvolle Zucht und nachhaltiger Wildfang",sections:[{kop:"Drei Kennzeichnungen, verschiedene Fragen",alineas:["Möchten Sie Bio-Fisch, verantwortungsvoll gezüchteten Fisch oder nachhaltigen Wildfang? Das sind verschiedene Wünsche. Prüfen Sie, welches Siegel tatsächlich zum gewählten Produkt gehört, und fragen Sie nach, wenn eine Kennzeichnung unklar ist."]},{kop:"Biologische Zucht",alineas:["Bio steht für zertifizierte Zucht nach Bio-Regeln. Eine Herkunftsgeschichte oder ein Lieferantenname ersetzt diese Zertifizierung nicht. Fragen Sie, welche Bio-Produkte aktuell verfügbar sind."]},{kop:"ASC und MSC",alineas:["ASC betrifft verantwortungsvolle Aquakultur; MSC nachhaltigen Wildfang und Rückverfolgbarkeit in der Lieferkette. ASC ist nicht dasselbe wie Bio-Zertifizierung. Auch MSC ist kein Bio-Siegel."]},{kop:"So helfen wir bei der Auswahl",alineas:["An der Theke oder per WhatsApp besprechen wir Herkunft, Verfügbarkeit und Informationen zum konkreten Produkt. Unsere Bio-Fischseite stellt die Unterschiede übersichtlich dar."]}]}
 },
 "is-biologische-zalm-gezonder-omega-3": {
 en:{title:"Organic salmon and omega-3: what does a label tell you?",excerpt:"A farming label is not a personal health promise. Keep origin, certification and nutritional information separate.",photo:"Oven-baked salmon with vegetables",sections:[{kop:"Origin and nutrition are different questions",alineas:["Organic certification concerns production methods. It does not mean every organic fillet automatically contains more omega-3 than every other fillet. You need nutritional information about the particular product to know that."]},{kop:"No health promises",alineas:["We are happy to help you choose fish and answer questions about origin and preparation. For personal dietary advice, speak to a dietitian or another qualified health professional."]},{kop:"Choose salmon to suit your dish",alineas:["Fresh fillet for the oven, smoked salmon for salad or pasta: choose the fish that suits your dish. Ask about availability, origin and current product information when buying."]}]},
 de:{title:"Bio-Lachs und Omega-3: was sagt ein Siegel aus?",excerpt:"Ein Zuchtsiegel ist kein persönliches Gesundheitsversprechen. Herkunft, Zertifizierung und Nährwertangaben getrennt betrachten.",photo:"Ofenlachs mit Gemüse",sections:[{kop:"Herkunft und Nährwert sind verschiedene Fragen",alineas:["Eine Bio-Zertifizierung betrifft die Produktionsweise. Daraus folgt nicht, dass jedes Bio-Filet automatisch mehr Omega-3 enthält als jedes andere Filet. Dafür benötigen Sie Nährwertangaben zum konkreten Produkt."]},{kop:"Keine Gesundheitsversprechen",alineas:["Wir helfen gern bei der Fischwahl und bei Fragen zu Herkunft und Zubereitung. Für persönliche Ernährungsberatung ist eine qualifizierte Ernährungsfachkraft oder ein anderer befugter Gesundheitsberuf zuständig."]},{kop:"Lachs passend zum Gericht wählen",alineas:["Frisches Filet für den Ofen, Räucherlachs für Salat oder Pasta: Wählen Sie den Fisch passend zum Gericht. Fragen Sie beim Kauf nach Verfügbarkeit, Herkunft und aktuellen Produktinformationen."]}]}
 },
 "hollandse-nieuwe-waarom-juni-haring-anders-smaakt": {
 en:{title:"Hollandse Nieuwe: why June’s herring tastes different",excerpt:"Each June, the Netherlands welcomes the new herring. What makes Hollandse Nieuwe special? Its rich, delicate texture.",photo:"Dutch new-season herring with chopped onion and gherkin on a white plate",sections:[{alineas:["Herring is available throughout the year. Hollandse Nieuwe marks the arrival of the new season, traditionally in June. The exact start depends on the fish and is announced each year."]},{kop:"Richness at the right moment",alineas:["In spring, herring feeds on plankton in the North Sea and builds its fat reserves before spawning. The fish chosen for new-season Dutch herring has the richness needed for its characteristic creamy texture.","Traditional preparation and ripening are important too. The herring is gibbed, leaving the pancreas in place; its enzymes help develop the tender texture. It is not simply any fresh herring sold in June."]},{kop:"How to enjoy it",alineas:["Some people prefer herring plain, perhaps with chopped onion. Others enjoy it in a soft roll with gherkin. You can eat it traditionally by holding the tail or ask for it cut into pieces.","In our shop and at the market, we prepare the herring when you ask for it, keeping the serving fresh rather than leaving cut pieces out for hours."]}]},
 de:{title:"Hollandse Nieuwe: warum der Juni-Matjes anders schmeckt",excerpt:"Jeden Juni freut sich die Niederlande auf den neuen Matjes. Was macht Hollandse Nieuwe besonders? Seine milde, cremige Struktur.",photo:"Hollandse Nieuwe mit gehackten Zwiebeln und Gewürzgurke auf einem weißen Teller",sections:[{alineas:["Matjes ist das ganze Jahr erhältlich. Hollandse Nieuwe steht für den Beginn der neuen Saison, traditionell im Juni. Der genaue Start hängt vom Fisch ab und wird jedes Jahr bekannt gegeben."]},{kop:"Reichhaltig zum richtigen Zeitpunkt",alineas:["Im Frühjahr ernährt sich der Hering von Plankton in der Nordsee und legt vor dem Laichen Fettreserven an. Der für Hollandse Nieuwe ausgewählte Fisch besitzt die nötige Reichhaltigkeit für seine typische cremige Struktur.","Auch traditionelle Verarbeitung und Reifung sind wichtig. Beim Kehlen bleibt die Bauchspeicheldrüse im Fisch; ihre Enzyme tragen zur zarten Struktur bei. Nicht jeder frische Hering, der im Juni verkauft wird, ist automatisch Hollandse Nieuwe."]},{kop:"So genießen Sie ihn",alineas:["Manche mögen Matjes pur, höchstens mit gehackten Zwiebeln. Andere genießen ihn im weichen Brötchen mit Gewürzgurke. Sie können ihn traditionell am Schwanz halten oder in Stücke schneiden lassen.","Im Geschäft und am Markt bereiten wir den Matjes zu, wenn Sie ihn bei uns holen. So bleibt die Portion frisch, statt geschnittene Stücke stundenlang liegen zu lassen."]}]}
 },
 "sinds-1938-de-geschiedenis-van-schaaps-vis": {
 en:{title:"Since 1938: generations of fish on the Herenstraat",excerpt:"From Gerrit Schaap’s shop in 1938 to today: the story of a familiar Leiden fishmonger in five chapters.",photo:"Fresh cod, a fishmonger’s classic",sections:[{alineas:["Walk along the Herenstraat in Leiden and you may notice fresh fish, fried kibbeling and smoked mackerel before you see the shop. Number 48 has housed Schaap’s Vishandel since 1938. This is the story of a business that has served generations of Leiden residents."]},{kop:"1938 — Gerrit Schaap starts the business",alineas:["Gerrit Schaap opened his fish shop when neighbourhood fishmongers were part of everyday life in Leiden. His name stayed with the shop and remains above it today."]},{kop:"1957 — the Haasnoot family takes over",alineas:["Cor Haasnoot began working for Mr Schaap at thirteen, learning the trade from the ground up. He took over the business in 1957. The Schaap name stayed as a tribute to the founder, and the Haasnoot family became associated with it throughout fish-loving Leiden."]},{kop:"2009 — the third generation",alineas:["In 2009, the third generation officially took over. The shop moved into the twenty-first century while keeping the personal, friendly atmosphere valued by customers. A visit is about advice and conversation as well as fish."]},{kop:"2018 — eighty years of memories",alineas:["On 1 January 2018, the business celebrated eighty years. Customers contributed photographs and memories for an anniversary book, reflecting how the shop has been part of everyday life in the city."]},{kop:"Today — looking towards the fourth generation",alineas:["Alongside the Herenstraat shop, the team also visits Leiden’s market on Wednesdays and Saturdays and Hoogvliet in Voorschoten on Fridays. The range has grown and the website has arrived, but the heart of the business remains fresh fish, honest advice and a good conversation."]}]},
 de:{title:"Seit 1938: Generationen von Fisch an der Herenstraat",excerpt:"Vom Geschäft Gerrit Schaaps im Jahr 1938 bis heute: die Geschichte einer vertrauten Leidener Fischhandlung in fünf Kapiteln.",photo:"Frischer Kabeljau, ein Klassiker beim Fischhändler",sections:[{alineas:["Wer durch die Herenstraat in Leiden geht, bemerkt vielleicht frischen Fisch, frittierte Kibbeling und Räuchermakrele, bevor das Geschäft zu sehen ist. An der Nummer 48 befindet sich Schaap’s Vishandel seit 1938. Das ist die Geschichte eines Betriebs, der Generationen von Leidenern versorgt hat."]},{kop:"1938 — Gerrit Schaap beginnt",alineas:["Gerrit Schaap eröffnete seine Fischhandlung in einer Zeit, in der lokale Fischhändler zum Alltag in Leiden gehörten. Sein Name blieb mit dem Geschäft verbunden und steht bis heute darüber."]},{kop:"1957 — die Familie Haasnoot übernimmt",alineas:["Cor Haasnoot begann mit dreizehn Jahren bei Herrn Schaap zu arbeiten und lernte das Handwerk von Grund auf. 1957 übernahm er den Betrieb. Der Name Schaap blieb als Ehrung des Gründers erhalten; so wurde die Familie Haasnoot im fischliebenden Leiden mit diesem Namen verbunden."]},{kop:"2009 — die dritte Generation",alineas:["2009 übernahm die dritte Generation offiziell den Betrieb. Das Geschäft ging mit der Zeit und bewahrte zugleich die persönliche, freundliche Atmosphäre, die Kunden schätzen. Zum Besuch gehören Beratung und Gespräche ebenso wie Fisch."]},{kop:"2018 — achtzig Jahre Erinnerungen",alineas:["Am 1. Januar 2018 feierte der Betrieb sein achtzigjähriges Bestehen. Kunden steuerten Fotos und Erinnerungen zu einem Jubiläumsbuch bei — ein Zeichen dafür, wie sehr das Geschäft zum Stadtleben gehört."]},{kop:"Heute — mit Blick auf die vierte Generation",alineas:["Neben dem Geschäft an der Herenstraat ist das Team mittwochs und samstags auf dem Leidener Markt und freitags bei Hoogvliet in Voorschoten. Das Sortiment ist gewachsen und eine Website hinzugekommen, doch der Kern bleibt: frischer Fisch, ehrliche Beratung und ein gutes Gespräch."]}]}
 },
 "wilde-zalm-vs-kweekzalm-waarom-wij-varlaks-kiezen": {
 en:{title:"Wild or farmed salmon? Start with its origin",excerpt:"Wild catch and farming tell different stories. Ask about the specific origin, then choose the salmon that suits your dish.",photo:"Fresh salmon fillet with lemon and dill",sections:[{kop:"Not all wild or farmed fish is alike",alineas:["The word wild or farmed alone is not enough to assess a product. Also ask about the supplier, origin and any certification of the particular fish."]},{kop:"Why we offer VÅRLAKS",alineas:["VÅRLAKS describes salmon from family businesses in northern Norway, with traceability from egg to plate. More information and the presentation film are on the supplier’s website. Ask us about current product certification."]},{kop:"From fillet to dish",alineas:["Do you want to pan-fry salmon, bake it or use smoked salmon? Our recipes help you choose. Send us a WhatsApp message about current availability; only seafood platters can be ordered online."]}]},
 de:{title:"Wildlachs oder Zuchtlachs? Mit der Herkunft beginnen",excerpt:"Wildfang und Zucht erzählen unterschiedliche Geschichten. Fragen Sie nach der konkreten Herkunft und wählen Sie dann den Lachs passend zu Ihrem Gericht.",photo:"Frisches Lachsfilet mit Zitrone und Dill",sections:[{kop:"Nicht jeder Wild- oder Zuchtfisch ist gleich",alineas:["Die Begriffe Wildfang oder Zucht allein reichen zur Beurteilung eines Produkts nicht aus. Fragen Sie auch nach Lieferant, Herkunft und einem möglichen Siegel des konkreten Fischs."]},{kop:"Warum wir VÅRLAKS anbieten",alineas:["VÅRLAKS beschreibt Lachs aus Familienbetrieben in Nordnorwegen mit Rückverfolgbarkeit vom Ei bis zum Teller. Weitere Informationen und den Präsentationsfilm finden Sie auf der Website des Lieferanten. Die aktuelle Produktzertifizierung können Sie bei uns erfragen."]},{kop:"Vom Filet zum Gericht",alineas:["Möchten Sie Lachs in der Pfanne braten, im Ofen zubereiten oder Räucherlachs verwenden? Unsere Rezepte helfen bei der Auswahl. Schreiben Sie uns per WhatsApp zur aktuellen Verfügbarkeit; nur Fischplatten können online bestellt werden."]}]}
 },
 "waarom-staat-makreel-op-rood": {
 en:{title:"Why is mackerel rated red? An honest explanation",excerpt:"Good Fish changed its advice for North-East Atlantic mackerel in April 2025. Origin and fishing method matter when checking a specific product.",photo:"Mackerel spread on bread",sections:[{alineas:["A sustainability rating is not a food-safety judgement. Ask us about the origin and fishing method of the mackerel offered."]},{kop:"What is the concern?",alineas:["Good Fish’s April 2025 warning concerns overfishing and insufficient international catch agreements.","Check the current VISwijzer entry for the relevant fishery rather than assuming all mackerel has the same rating."]},{kop:"What does that mean at our counter?",alineas:["We offer mackerel, but do not present it as automatically sustainable.","Ask about certification and alternatives. A product name alone does not establish its environmental rating."]},{kop:"Making your choice",alineas:["Use the current fish guide and discuss options with us. Choose a verifiable certification or origin rather than relying on a general claim."]}]},
 de:{title:"Warum steht Makrele auf Rot? Eine ehrliche Erklärung",excerpt:"Good Fish änderte im April 2025 die Empfehlung für nordostatlantische Makrele. Herkunft und Fangmethode sind bei der Prüfung eines Produkts wichtig.",photo:"Makrelensalat auf Brot",sections:[{alineas:["Eine Nachhaltigkeitsbewertung ist kein Urteil über Lebensmittelsicherheit. Fragen Sie uns nach Herkunft und Fangmethode der angebotenen Makrele."]},{kop:"Was ist das Problem?",alineas:["Die Warnung von Good Fish aus April 2025 betrifft Überfischung und fehlende gemeinsame Fangvereinbarungen.","Prüfen Sie den aktuellen VISwijzer-Eintrag für die konkrete Fischerei, statt für jede Makrele dieselbe Bewertung anzunehmen."]},{kop:"Was bedeutet das an unserer Theke?",alineas:["Wir bieten Makrele an, stellen sie aber nicht automatisch als nachhaltig dar.","Fragen Sie nach Zertifizierung und Alternativen. Ein Produktname allein belegt keine Umweltbewertung."]},{kop:"Ihre Auswahl treffen",alineas:["Nutzen Sie den aktuellen Fischratgeber und besprechen Sie Möglichkeiten mit uns. Achten Sie auf nachprüfbare Zertifizierung oder Herkunft statt auf pauschale Aussagen."]}]}
 },
 "zalm-bakken-pan-of-oven": {
 en:{title:"Cooking salmon: pan or oven?",excerpt:"Want a crisp surface, or prefer to let the oven do the work? Choose the method that suits your salmon and your evening.",photo:"Oven-baked salmon with lemon and dill",sections:[{kop:"The pan: for a fried crust",alineas:["Pat the salmon dry before you start: a wet surface will not brown as well. Choose a pan that holds the pieces side by side. Let the fish cook undisturbed at first, then turn carefully with a wide spatula. The time depends on fillet thickness and your heat source.","Is the skin still on? Ask us how best to cook it when you buy the fish. We are happy to discuss portion size and preparation."]},{kop:"The oven: useful for several portions",alineas:["Place the fillets side by side in a baking dish. Lemon and dill add flavour without overpowering the salmon. Check the fish as it cooks: the time varies with thickness and oven. Our lemon and dill recipe guides you step by step."]},{kop:"Fresh or smoked salmon?",alineas:["Choose fresh salmon fillet for frying or baking. Smoked salmon is a different product: it works in salads, on bread or added to pasta at the last moment. Choose the dish first, then the appropriate salmon."]},{kop:"Choosing your salmon in Leiden",alineas:["Find Schaap’s Vishandel at Herenstraat 48. The shop is open Tuesday to Saturday. Ask about current availability on WhatsApp or visit for advice. Only seafood platters can be ordered online."]}]},
 de:{title:"Lachs zubereiten: Pfanne oder Ofen?",excerpt:"Eine knusprige Außenseite oder lieber den Ofen arbeiten lassen? Wählen Sie die Zubereitung passend zu Ihrem Lachs und Ihrem Abend.",photo:"Ofenlachs mit Zitrone und Dill",sections:[{kop:"Die Pfanne: für eine gebratene Kruste",alineas:["Den Lachs vor dem Braten trocken tupfen: Eine nasse Oberfläche bräunt schlechter. Eine Pfanne wählen, in der die Stücke nebeneinander liegen. Den Fisch zunächst in Ruhe braten und vorsichtig mit einem breiten Pfannenwender wenden. Die Zeit hängt von Filetdicke und Wärmequelle ab.","Hat der Lachs noch Haut? Fragen Sie beim Kauf nach der besten Zubereitung. Wir beraten gern zu Portionsgröße und Garmethode."]},{kop:"Der Ofen: praktisch für mehrere Portionen",alineas:["Die Filets nebeneinander in eine Auflaufform legen. Zitrone und Dill geben Geschmack, ohne den Lachs zu überdecken. Den Fisch während des Garens prüfen: Die Zeit variiert je nach Dicke und Ofen. Unser Rezept mit Zitrone und Dill führt Sie Schritt für Schritt durch die Zubereitung."]},{kop:"Frischer Lachs oder Räucherlachs?",alineas:["Zum Braten oder Backen frisches Lachsfilet wählen. Räucherlachs ist ein anderes Produkt: Er passt in Salate, auf Brot oder zuletzt in eine Pasta. Wählen Sie zuerst das Gericht und dann den passenden Lachs."]},{kop:"Ihren Lachs in Leiden auswählen",alineas:["Schaap’s Vishandel finden Sie an der Herenstraat 48. Das Geschäft ist von Dienstag bis Samstag geöffnet. Fragen Sie per WhatsApp nach der aktuellen Verfügbarkeit oder kommen Sie zur Beratung vorbei. Nur Fischplatten können online bestellt werden."]}]}
 },
 "hoeveel-vis-per-persoon": {
 en:{title:"How much fish per person? Choosing your portions",excerpt:"Lunch, main course or sharing snacks: the right amount depends on your menu. These questions make choosing easier.",photo:"Cod with lemon butter sauce, potatoes and vegetables",sections:[{kop:"Start with the fish’s role in the meal",alineas:["Is fish the main course or a small part of a larger menu? A fillet alongside potatoes and vegetables needs a different portion from a small toast starter. Consider your guests’ appetites and any other dishes too."]},{kop:"Whole fish is not the same as fillet",alineas:["The weight of a whole fish includes its head, bones and skin. You cannot apply a fillet weight directly to a whole fish. Tell us how you want to cook it and how many people are eating; we can advise on a suitable piece."]},{kop:"Follow the recipe’s shopping list",alineas:["Our recipes with a stated number of servings provide a practical starting point. For example, our cod recipe uses four 150 g fillets for four people, with sides. A recipe without a serving count needs additional adjustment of quantities."]},{kop:"A seafood platter for a party",alineas:["When configuring a platter, check its stated size. Tell us whether it is for shared snacks or part of a meal. Online ordering is only for seafood platters. For individual fish, different amounts or special requests, send us a WhatsApp message and we will discuss the options."]}]},
 de:{title:"Wie viel Fisch pro Person? So wählen Sie die Portionen",excerpt:"Mittagessen, Hauptgericht oder Häppchen: Die passende Menge hängt vom Menü ab. Diese Fragen erleichtern die Auswahl.",photo:"Kabeljau mit Zitronenbuttersauce, Kartoffeln und Gemüse",sections:[{kop:"Mit der Rolle des Fischs beginnen",alineas:["Ist Fisch das Hauptgericht oder ein kleiner Teil eines größeren Menüs? Ein Filet neben Kartoffeln und Gemüse braucht eine andere Portion als ein kleines Toaststück als Vorspeise. Beachten Sie auch den Appetit Ihrer Gäste und weitere Speisen."]},{kop:"Ganzer Fisch ist nicht dasselbe wie Filet",alineas:["Beim ganzen Fisch zählen Kopf, Gräten und Haut zum Gewicht. Ein Filetgewicht lässt sich deshalb nicht direkt auf einen ganzen Fisch übertragen. Erzählen Sie uns, wie Sie den Fisch zubereiten möchten und für wie viele Personen; wir beraten zu einer passenden Größe."]},{kop:"Die Einkaufsliste des Rezepts nutzen",alineas:["Unsere Rezepte mit angegebener Personenzahl bieten einen praktischen Ausgangspunkt. Das Kabeljaurezept verwendet zum Beispiel vier Filets à 150 g für vier Personen, mit Beilagen. Ein Rezept ohne Portionsangabe braucht eine zusätzliche Abstimmung der Mengen."]},{kop:"Eine Fischplatte für eine Feier",alineas:["Beachten Sie beim Zusammenstellen die angegebene Plattengröße. Sagen Sie uns, ob es um Häppchen oder einen Teil einer Mahlzeit geht. Online-Bestellungen sind ausschließlich für Fischplatten möglich. Für einzelnen Fisch, andere Mengen oder besondere Wünsche schreiben Sie uns per WhatsApp; wir besprechen gern die Möglichkeiten."]}]}
 },
 "viskalender-welke-vis-in-welk-seizoen": {
 en:{title:"The fish calendar: which fish suits each season?",excerpt:"Fish has seasons, just like fruit and vegetables. Explore seasonal ideas, then ask about this week’s supply and prices.",photo:"Pan-fried plaice with tomato and olives",sections:[{alineas:["Fish quality and availability vary with spawning, water temperature, feeding and supply. A seasonal calendar is useful inspiration, not a stock list or price guarantee. Ask which fish is in good condition this week and where it comes from."]},{kop:"Spring (March–May)",alineas:["Plaice is often associated with late spring and summer, after recovering from winter spawning. Sea bass and sea bream also suit light spring dishes, although origin and farming affect availability. Oysters vary by species and producer: ask about the current delivery rather than relying only on a month."]},{kop:"Summer (June–August)",alineas:["The new Dutch herring season usually begins in June; its exact start is announced each year. Mackerel, sardines and anchovies can suit summer dishes, but discuss origin and fishing method as well as taste. Zeeland bottom-grown mussels usually begin in summer, not only in months with an ‘r’. The exact start depends on harvest quality and can be earlier."]},{kop:"Autumn (September–November)",alineas:["Mussels remain a popular autumn choice. The usual Zeeland bottom-grown season runs from around July to April; the old ‘r in the month’ rule is not a reliable availability calendar. Shrimp, cod and whiting also offer ideas for autumn meals, depending on supply."]},{kop:"Winter (December–February)",alineas:["Cod, whiting and other white fish suit warming winter meals. Turbot, brill and haddock provide further possibilities depending on origin and supply. Oysters, smoked eel and smoked salmon are popular around the holidays, but popularity does not guarantee stock.","Not sure what to choose this week? Visit or call us. We can discuss the current delivery, preparation and suitable alternatives."]}]},
 de:{title:"Der Fischkalender: welcher Fisch passt zu welcher Saison?",excerpt:"Fisch hat Saison, genau wie Obst und Gemüse. Entdecken Sie saisonale Ideen und fragen Sie nach dem aktuellen Angebot und den Preisen.",photo:"Gebratene Scholle mit Tomaten und Oliven",sections:[{alineas:["Qualität und Verfügbarkeit von Fisch hängen unter anderem von Laichzeit, Wassertemperatur, Nahrung und Angebot ab. Ein Saisonkalender bietet Anregungen, ist aber keine Bestandsliste oder Preisgarantie. Fragen Sie, welcher Fisch diese Woche gut ist und woher er kommt."]},{kop:"Frühling (März–Mai)",alineas:["Scholle wird häufig mit spätem Frühling und Sommer verbunden, nachdem sie sich von der winterlichen Laichzeit erholt hat. Wolfsbarsch und Dorade passen ebenfalls zu leichten Frühlingsgerichten, wobei Herkunft und Zucht die Verfügbarkeit beeinflussen. Austern unterscheiden sich nach Art und Erzeuger: Fragen Sie nach der aktuellen Lieferung statt nur auf einen Monat zu achten."]},{kop:"Sommer (Juni–August)",alineas:["Die neue niederländische Matjessaison beginnt meist im Juni; der genaue Beginn wird jährlich bekannt gegeben. Makrele, Sardinen und Sardellen passen zu Sommergerichten, aber besprechen Sie neben dem Geschmack auch Herkunft und Fangmethode. Zeeländische Bodenkulturmuscheln sind meist schon im Sommer verfügbar, nicht nur in Monaten mit einem ‚r‘. Der genaue Beginn hängt von der Erntequalität ab und kann früher liegen."]},{kop:"Herbst (September–November)",alineas:["Miesmuscheln sind im Herbst beliebt. Die übliche Saison zeeländischer Bodenkulturmuscheln reicht ungefähr von Juli bis April; die alte Regel mit dem ‚r im Monat‘ ist kein zuverlässiger Verfügbarkeitskalender. Garnelen, Kabeljau und Wittling bieten je nach Angebot weitere Ideen für Herbstgerichte."]},{kop:"Winter (Dezember–Februar)",alineas:["Kabeljau, Wittling und anderer Weißfisch passen zu wärmenden Wintergerichten. Steinbutt, Glattbutt und Schellfisch bieten je nach Herkunft und Angebot weitere Möglichkeiten. Austern, Räucheraal und Räucherlachs sind an Feiertagen beliebt, doch Beliebtheit garantiert keinen Bestand.","Unsicher, was Sie diese Woche wählen sollen? Kommen Sie vorbei oder rufen Sie uns an. Wir besprechen die aktuelle Lieferung, Zubereitung und passende Alternativen."]}]}
 },
 "kibbeling-voorschoten-vrijdag": {
 en:{title:"Kibbeling in Voorschoten: make it a meal",excerpt:"Pick up kibbeling in Voorschoten on Friday at Hoogvliet. Discover what to serve with it, why we choose ravigote sauce and how to plan your meal.",photo:"Crisp kibbeling with lemon and sauce as meal inspiration",sections:[
 {kop:"Pick up kibbeling on Friday at Hoogvliet",alineas:["Want kibbeling in Voorschoten without lots of cooking afterwards? Schaap’s Vishandel stands in the Hoogvliet car park every Friday from 08:00 to 17:30. Pick up fried fish while shopping or take something home in the late afternoon. This is our weekly stall, not a shop open every day in Voorschoten.","Lunch needs a different amount from dinner for the whole family. Tell us how many people are eating and what you plan to serve alongside. We can help you choose a suitable quantity. For a particular product or a larger amount, ask about options beforehand on WhatsApp; supply and availability vary."]},
 {kop:"Ravigote sauce with kibbeling",alineas:["We serve ravigote sauce with our kibbeling. Its fresh, herby flavour complements the crisp fish coating. Take the sauce separately if you want to control how much you use. You can then serve some fish without sauce for anyone who prefers it that way.","Kibbeling and lekkerbek are different forms of fried fish. Kibbeling consists of small pieces; our lekkerbek is a fried hake fillet in batter. Choose according to your preference and how you want to eat it. Ask which fish we are using for kibbeling and read our explanation of the difference if you are unsure."]},
 {kop:"Three ways to serve kibbeling",alineas:["For a quick lunch, serve kibbeling with bread, cucumber and sauce on the side. No second hot dish is needed. This also works if everyone wants a different-sized portion.","For dinner, make a salad or coleslaw at home first and boil or roast the potatoes. Pick up the kibbeling close to mealtime. That way, you are not preparing the sides while the fried fish waits.","For a lighter meal, combine fish with plenty of vegetables and a modest side dish. Try the salad from our kibbeling and ravigote sauce recipe. The article photo is meal inspiration, not a fixed portion or compulsory combination supplied at the stall."]},
 {kop:"Plan your visit around mealtime",alineas:["The coating is crispest when fried fish is eaten soon after purchase. If you still have lots of shopping to do, plan your order of errands accordingly. Prefer to cook at your own pace? A fresh fillet for the pan or oven may suit you better than ready-fried fish.","Our Friday hours run until 17:30, so you can also visit later in the afternoon. Stock is not guaranteed until closing: check availability beforehand if you are coming for a specific product. On other days, see our Leiden shop and other sales locations on the locations page."]}
 ],questions:[{v:"Where can I get kibbeling in Voorschoten on Friday?",a:"At Schaap’s Vishandel in the Hoogvliet car park, every Friday from 08:00 to 17:30. Ask about current availability."},{v:"Which sauce do you serve with kibbeling?",a:"Ravigote sauce. Tell us your preferences at the stall; we are happy to discuss what is possible."},{v:"Can I order individual portions of kibbeling online?",a:"No. Only seafood platters have an online order route. For kibbeling or other fish, ask on WhatsApp about availability and options."}]},
 de:{title:"Kibbeling in Voorschoten: so wird daraus eine Mahlzeit",excerpt:"Kibbeling in Voorschoten holen? Besuchen Sie uns freitags bei Hoogvliet. Welche Beilagen passen, warum wir Ravigotesauce wählen und wie Sie Ihr Essen planen.",photo:"Knusprige Kibbeling mit Zitrone und Sauce als Anregung für eine Mahlzeit",sections:[
 {kop:"Kibbeling freitags bei Hoogvliet holen",alineas:["Kibbeling in Voorschoten holen und danach nicht aufwendig kochen? Schaap’s Vishandel steht freitags von 08:00 bis 17:30 auf dem Parkplatz bei Hoogvliet. Sie können während des Einkaufs Backfisch holen oder am späten Nachmittag etwas mit nach Hause nehmen. Dies ist unser wöchentlicher Stand, kein täglich geöffnetes Geschäft in Voorschoten.","Für ein Mittagessen benötigen Sie andere Mengen als für ein Familienabendessen. Sagen Sie uns, wie viele Personen mitessen und welche Beilagen Sie planen. Dann helfen wir Ihnen bei der passenden Menge. Für ein bestimmtes Produkt oder größere Mengen fragen Sie vorher per WhatsApp nach den Möglichkeiten; Angebot und Verfügbarkeit variieren."]},
 {kop:"Ravigotesauce zu Kibbeling",alineas:["Zu unseren Kibbeling gehört Ravigotesauce. Die frische, würzige Sauce passt zur knusprigen Hülle. Nehmen Sie die Sauce separat, wenn Sie selbst über die Menge entscheiden möchten. So können Sie zu Hause auch einen Teil ohne Sauce servieren.","Kibbeling und Lekkerbek sind unterschiedliche Arten von Backfisch. Kibbeling bestehen aus kleinen Stücken; unser Lekkerbek ist ein Seehechtfilet im Backteig, frittiert. Entscheiden Sie nach Vorliebe und Verwendungszweck. Fragen Sie am Stand, welchen Fisch wir für Kibbeling verwenden, und lesen Sie bei Unsicherheit unsere Erklärung zum Unterschied."]},
 {kop:"Drei Möglichkeiten, Kibbeling zu servieren",alineas:["Für ein schnelles Mittagessen Kibbeling mit Brot, etwas Gurke und separater Sauce servieren. Ein zweites warmes Gericht ist nicht nötig. Das passt auch, wenn nicht alle die gleiche Menge essen möchten.","Für das Abendessen zuerst zu Hause Salat oder Krautsalat vorbereiten und die Kartoffeln kochen oder backen. Holen Sie die Kibbeling danach möglichst kurz vor dem Essen. So müssen Sie die Beilagen nicht zubereiten, während der Backfisch wartet.","Für eine leichtere Mahlzeit Fisch mit viel Gemüse und einer kleinen Beilage kombinieren. Probieren Sie den Salat aus unserem Rezept mit Kibbeling und Ravigotesauce. Das Foto ist eine Servieranregung, keine feste Portion oder verbindliche Zusammenstellung vom Stand."]},
 {kop:"Das Abholen rund um die Essenszeit planen",alineas:["Die Hülle bleibt am knusprigsten, wenn Sie Backfisch kurz nach dem Kauf essen. Wenn Sie noch länger einkaufen müssen, berücksichtigen Sie das bei Ihrer Planung. Möchten Sie lieber selbst zu Ihrer Wunschzeit kochen? Dann passt ein frisches Filet für Pfanne oder Ofen möglicherweise besser als fertig frittierter Fisch.","Freitags sind wir bis 17:30 da, also auch eine Möglichkeit für einen Besuch am späten Nachmittag. Bestand ist nicht bis Ladenschluss garantiert: Fragen Sie vorher nach, wenn Sie ein bestimmtes Produkt möchten. Für andere Tage finden Sie unser Geschäft in Leiden und weitere Verkaufsstellen auf der Standortseite."]}
 ],questions:[{v:"Wo bekomme ich freitags Kibbeling in Voorschoten?",a:"Bei Schaap’s Vishandel auf dem Parkplatz bei Hoogvliet, freitags von 08:00 bis 17:30. Fragen Sie nach der aktuellen Verfügbarkeit."},{v:"Welche Sauce servieren Sie zu Kibbeling?",a:"Ravigotesauce. Teilen Sie uns Ihre Wünsche am Stand mit; wir besprechen gern die Möglichkeiten."},{v:"Kann ich einzelne Portionen Kibbeling online bestellen?",a:"Nein. Nur Fischplatten haben einen Online-Bestellweg. Für Kibbeling oder andere Fische fragen Sie per WhatsApp nach Verfügbarkeit und Möglichkeiten."}]}
 },
 "vis-avondeten-voorschoten": {
 en:{title:"Fish for dinner in Voorschoten: three ideas",excerpt:"Pick up fish for Friday dinner in Voorschoten: try a fish parcel, salmon or cod. Our Hoogvliet stall is open from 08:00 to 17:30.",photo:"Cooked fish parcel with vegetables for dinner",sections:[
 {kop:"From the fish stall to your Friday dinner",alineas:["Looking for fish for Friday dinner in Voorschoten? Visit Schaap’s Vishandel in the Hoogvliet car park from 08:00 to 17:30. You do not need a complicated menu: decide how you want to cook, how much time you have and how many people you are feeding. With that information, we can help you choose a suitable fillet.","These three ideas differ in cooking method, not just fish type. A parcel is useful for cooking fish and vegetables together. Salmon works in a simple baking dish. Cod can be pan-fried and served with side dishes. Read the full recipe before shopping so you have the vegetables and other ingredients too."]},
 {kop:"Idea 1: a fish parcel with vegetables",alineas:["For an oven parcel, place fish and thinly sliced vegetables in baking paper. Our recipe uses one fillet per person with lemon and a little butter. The parcel keeps fish and vegetables together and looks attractive on the table without needing several pans.","Ask for a fillet that suits the recipe and tell us if you have cod or another fish in mind. Fillet thickness affects cooking time. Use the full recipe as a guide and check the result: one fixed baking time does not suit every size of fish."]},
 {kop:"Idea 2: oven-baked salmon with sides",alineas:["Our VÅRLAKS salmon is a favourite at the counter. Fresh salmon fillet suits an oven meal with lemon and dill, or a vegetable traybake. Choose fresh fillet for cooking; smoked salmon is a different product needing a different approach.","For several diners, ask for portions of similar thickness so they cook evenly. Discuss whether you want the skin left on. Origin and certification relate to the particular delivery: a salmon’s name alone is not proof of organic certification."]},
 {kop:"Idea 3: pan-fried cod",alineas:["Cod with lemon butter sauce is an option if you enjoy pan cooking. Our four-person recipe uses four 150 g fillets and sides. That is an example for this dish, not a fixed rule for every menu or appetite.","Prepare the potatoes and vegetables first or time them so everything is ready together. Pat the fish dry before frying and turn it carefully. Ask us about a suitable size for your pan. If cod is unavailable, discuss an alternative and whether the cooking method needs adjusting."]},
 {kop:"Keep fresh fish chilled on the way home",alineas:["Plan your shopping so fresh fish is not left unrefrigerated for long. The Dutch Nutrition Centre recommends a cool bag for transport and prompt refrigeration at home. It advises eating unpackaged fresh fish from the fishmonger preferably on the day of purchase; for packaged fish, follow the use-by date.","Discuss when you plan to cook and follow the product’s storage advice. To check your preferred fish is available on Friday, message us on WhatsApp with the fish type, number of people and a request for Voorschoten. We will discuss what is possible. Only seafood platters can be configured and ordered online."]}
 ],questions:[{v:"How late can I get fish in Voorschoten on Friday?",a:"Our Hoogvliet stall is open on Fridays from 08:00 until 17:30. Check availability of a particular product beforehand on WhatsApp."},{v:"Which fish suits a simple dinner?",a:"A fresh fillet in an oven parcel, oven-baked salmon or pan-fried cod are three options. Choose a recipe and discuss portions and current supply at the stall."},{v:"Can I enquire about salmon for collection in Voorschoten?",a:"Ask on WhatsApp about availability, stating the number of diners and your collection preference. A message is not a confirmed order; we agree the options and price with you."}]},
 de:{title:"Fisch zum Abendessen in Voorschoten: drei Ideen",excerpt:"Freitags Fisch zum Abendessen in Voorschoten holen? Wählen Sie ein Ofenpäckchen, Lachs oder Kabeljau. Unser Stand bei Hoogvliet ist von 08:00 bis 17:30 geöffnet.",photo:"Gegartes Fischpäckchen mit Gemüse zum Abendessen",sections:[
 {kop:"Vom Fischstand zum Freitagabendessen",alineas:["Sie möchten freitags in Voorschoten Fisch zum Abendessen holen? Bei Schaap’s Vishandel auf dem Hoogvliet-Parkplatz können Sie von 08:00 bis 17:30 vorbeikommen. Ein kompliziertes Menü ist nicht nötig: Entscheiden Sie, wie Sie kochen möchten, wie viel Zeit Sie haben und für wie viele Personen. Damit können wir Ihnen bei der Wahl eines passenden Filets helfen.","Die drei Ideen unterscheiden sich in der Zubereitung, nicht nur in der Fischart. Ein Päckchen ist praktisch, um Gemüse und Fisch gemeinsam zu garen. Lachs passt in eine einfache Auflaufform. Kabeljau lässt sich in der Pfanne braten und mit Beilagen servieren. Lesen Sie vor dem Einkaufen das vollständige Rezept, damit auch Gemüse und weitere Zutaten vorhanden sind."]},
 {kop:"Idee 1: ein Fischpäckchen mit Gemüse",alineas:["Für ein Ofenpäckchen legen Sie Fisch und dünn geschnittenes Gemüse in Backpapier. Unser Rezept verwendet ein Filet pro Person, Zitrone und etwas Butter. Das Päckchen hält Fisch und Gemüse zusammen und sieht auf dem Tisch schön aus, ohne mehrere Pfannen zu benötigen.","Fragen Sie nach einem zum Rezept passenden Filet und sagen Sie, ob Sie Kabeljau oder einen anderen Fisch möchten. Die Filetdicke beeinflusst die Garzeit. Nutzen Sie das vollständige Rezept als Orientierung und prüfen Sie das Ergebnis: Eine feste Backzeit passt nicht automatisch zu jeder Fischgröße."]},
 {kop:"Idee 2: Ofenlachs mit Beilagen",alineas:["Unser VÅRLAKS-Lachs ist ein Favorit an der Theke. Frisches Lachsfilet passt zu einem Ofengericht mit Zitrone und Dill oder einem Gemüsegericht vom Blech. Zum Braten frisches Filet wählen; Räucherlachs ist ein anderes Produkt und braucht eine andere Zubereitung.","Für mehrere Personen nach ähnlich dicken Portionen fragen, damit sie gleichzeitig garen. Besprechen Sie auch, ob die Haut am Filet bleiben soll. Herkunft und Siegel beziehen sich auf die konkrete Lieferung: Der Name eines Lachses allein ist kein Nachweis einer Bio-Zertifizierung."]},
 {kop:"Idee 3: Kabeljau aus der Pfanne",alineas:["Kabeljau mit Zitronenbuttersauce ist eine Möglichkeit für alle, die gern in der Pfanne kochen. Unser Rezept für vier Personen verwendet vier Filets à 150 g und Beilagen. Das ist ein Beispiel für dieses Gericht, keine feste Regel für jedes Menü oder jeden Appetit.","Kartoffeln und Gemüse zuerst vorbereiten oder so planen, dass alles gleichzeitig fertig ist. Das Filet vor dem Braten trocken tupfen und vorsichtig wenden. Fragen Sie uns nach einer passenden Größe für Ihre Pfanne. Ist Kabeljau nicht verfügbar, besprechen Sie eine Alternative und mögliche Anpassungen der Zubereitung."]},
 {kop:"Frischen Fisch gekühlt nach Hause bringen",alineas:["Planen Sie den Einkauf so, dass frischer Fisch nicht lange ungekühlt unterwegs ist. Das niederländische Ernährungszentrum empfiehlt eine Kühltasche und rasches Kühlen zu Hause. Unverpackten frischen Fisch vom Fischhändler möglichst am Kauftag essen; bei verpacktem Fisch das Verbrauchsdatum beachten.","Besprechen Sie beim Kauf, wann Sie kochen möchten, und beachten Sie die Lagerhinweise. Möchten Sie wissen, ob Ihr Wunschfisch freitags verfügbar ist? Schreiben Sie per WhatsApp Fischart, Personenzahl und den Wunsch nach Abholung in Voorschoten. Wir besprechen die Möglichkeiten. Nur Fischplatten lassen sich online zusammenstellen und bestellen."]}
 ],questions:[{v:"Bis wann bekomme ich freitags Fisch in Voorschoten?",a:"Unser Stand bei Hoogvliet ist freitags von 08:00 bis 17:30 geöffnet. Die Verfügbarkeit eines bestimmten Produkts können Sie vorher per WhatsApp erfragen."},{v:"Welcher Fisch passt zu einem einfachen Abendessen?",a:"Ein frisches Filet im Ofenpäckchen, Ofenlachs oder Kabeljau aus der Pfanne sind drei Möglichkeiten. Wählen Sie das Rezept und besprechen Sie Portionen und aktuelles Angebot am Stand."},{v:"Kann ich Lachs für Voorschoten vorab anfragen?",a:"Fragen Sie per WhatsApp nach Verfügbarkeit und nennen Sie Personenzahl und Abholwunsch. Eine Nachricht ist keine bestätigte Bestellung; Möglichkeiten und Preis stimmen wir mit Ihnen ab."}]}
 },
 "visschaal-borrel-voorschoten": {
 en:{title:"Choosing a seafood platter for a gathering in Voorschoten",excerpt:"Planning a party or birthday in Voorschoten? Choose a seafood platter around your guests, budget and preferences. Read what to arrange with us beforehand.",photo:"Example of a generous seafood platter with smoked fish, shrimp and salads",sections:[
 {kop:"Start with the occasion, not just the photo",alineas:["Choosing a seafood platter in Voorschoten starts with your plans. Will it be shared snacks alongside bread, cheese and other dishes, or the main part of the meal? Guest numbers alone do not determine the right quantity. Tell us how you intend to serve the platter.","At Schaap’s Vishandel, choose a drinks platter, family platter or party platter as a starting point. Photos are serving examples, not an exact picture of what you receive. Your platter can be considerably larger and filled according to your budget and wishes. Discuss special requests beforehand; a photo is not a stock guarantee."]},
 {kop:"How many guests are joining?",alineas:["Our drinks platter is intended for about four to six people, the family platter for eight to ten and the party platter for twelve to sixteen. Treat this as an initial guide. A long gathering with small bites needs a different quantity from a platter replacing a main course.","Tell us whether children are joining, what other food you will offer and whether some guests do not want fish or shellfish. We can discuss a suitable arrangement. Do not choose solely by platter name: the rest of your menu matters just as much."]},
 {kop:"Smoked fish, shrimp or a combination?",alineas:["A mixed sharing platter might include smoked salmon, mackerel, herring bites, shrimp and salads. The larger examples also show eel, prawns or oysters. Available fish and your preferences determine a suitable combination. Ask about the current contents if a particular item is important to you.","Guests who mainly enjoy smoked fish need not have the same platter as a group asking for shrimp. Optional extras help tailor the selection. Tell us if you want certain items served separately so we can discuss whether and how this can be done."]},
 {kop:"Agree budget and price in advance",alineas:["The online configurator shows starting prices and indicative charges for extras. The final price may vary with quantity, contents and special requests. We confirm the final amount before preparing the platter; do not treat an example photo as a fixed package with an unchangeable price.","If you have a budget for the whole gathering, tell us the amount, guest numbers and favourite products. This is more useful than simply asking for a large platter. Only seafood platters can be configured and ordered online. Discuss individual fish products or other requests with us on WhatsApp."]},
 {kop:"Collection for your gathering in Voorschoten",alineas:["Our fish stall is in the Hoogvliet car park in Voorschoten every Friday from 08:00 to 17:30. Arrange collection there with us in advance. An online request does not automatically mean a platter is ready at every location or time. Date, collection point and availability must be confirmed together.","Plan a few days ahead and contact us earlier around busy holidays. State the occasion, desired time, guest numbers, budget and any allergies. Do not assume allergen-free preparation: explain your needs so we can discuss options and limitations."]}
 ],questions:[{v:"Can I choose a seafood platter for Voorschoten online?",a:"Yes, you can configure seafood platters online. Agree the date and collection point with us; availability and the final price are confirmed."},{v:"Will my platter look exactly like the photo?",a:"No. The photo is an example. Size and contents are tailored to your guests, budget and wishes; your platter can be larger and your choices can change the price."},{v:"Can I collect a platter at Hoogvliet on Friday?",a:"Ask beforehand and obtain confirmation from us. Our Voorschoten stall is at Hoogvliet on Fridays from 08:00 to 17:30; collection of a specific platter is by arrangement."}]},
 de:{title:"Eine Fischplatte für Ihre Feier in Voorschoten wählen",excerpt:"Eine Feier oder ein Geburtstag in Voorschoten? Wählen Sie eine Fischplatte passend zu Gästen, Budget und Vorlieben. Was Sie vorher mit uns abstimmen können.",photo:"Beispiel einer großzügigen Fischplatte mit Räucherfisch, Garnelen und Salaten",sections:[
 {kop:"Mit dem Anlass beginnen, nicht nur mit dem Foto",alineas:["Die Wahl einer Fischplatte in Voorschoten beginnt bei Ihren Plänen. Sind es Häppchen neben Brot, Käse und anderen Speisen oder soll der Fisch den Hauptteil der Mahlzeit bilden? Die Gästezahl allein bestimmt nicht die passende Menge. Erzählen Sie uns, wie Sie die Platte servieren möchten.","Bei Schaap’s Vishandel können Sie eine kleine Platte, Familienplatte oder Festplatte als Ausgangspunkt wählen. Die Fotos zeigen Servierbeispiele, nicht genau das, was Sie erhalten. Die tatsächliche Platte kann deutlich größer sein und wird passend zu Budget und Wünschen gefüllt. Besondere Wünsche vorher besprechen; ein Foto ist keine Verfügbarkeitsgarantie."]},
 {kop:"Wie viele Gäste essen mit?",alineas:["Unsere kleine Platte ist für etwa vier bis sechs Personen gedacht, die Familienplatte für acht bis zehn und die Festplatte für zwölf bis sechzehn. Das ist eine erste Orientierung. Ein langer Abend mit kleinen Häppchen braucht andere Mengen als eine Platte, die das Hauptgericht ersetzt.","Sagen Sie uns, ob Kinder mitessen, welche anderen Speisen Sie anbieten und ob einzelne Gäste keinen Fisch oder keine Schalentiere möchten. Gemeinsam finden wir eine passende Zusammenstellung. Wählen Sie nicht nur nach dem Namen der Platte: Ihr übriges Menü ist ebenso wichtig."]},
 {kop:"Räucherfisch, Garnelen oder eine Mischung?",alineas:["Eine gemischte Platte kann Räucherlachs, Makrele, Matjeshäppchen, Garnelen und Salate enthalten. Die größeren Beispiele zeigen auch Aal, große Garnelen oder Austern. Verfügbarer Fisch und Ihre Wünsche bestimmen die passende Kombination. Fragen Sie nach der aktuellen Zusammenstellung, wenn ein bestimmter Bestandteil wichtig ist.","Gäste, die vor allem Räucherfisch mögen, brauchen nicht dieselbe Platte wie eine Gruppe mit einer Vorliebe für Garnelen. Wählbare Extras helfen bei der Anpassung. Teilen Sie auch mit, wenn bestimmte Produkte separat serviert werden sollen, damit wir die Umsetzung besprechen können."]},
 {kop:"Budget und Preis vorher abstimmen",alineas:["Der Online-Konfigurator zeigt Startpreise und ungefähre Kosten für Extras. Der Endpreis kann sich durch Menge, Zusammenstellung und besondere Wünsche ändern. Wir bestätigen den endgültigen Betrag vor der Zubereitung; ein Beispielbild ist kein festes Paket mit unveränderlichem Preis.","Haben Sie ein Budget für die gesamte Feier? Nennen Sie Betrag, Gästezahl und Lieblingsprodukte. Das hilft mehr als die bloße Bitte um eine große Platte. Nur Fischplatten können online zusammengestellt und bestellt werden. Einzelnen Fisch und andere Wünsche besprechen wir per WhatsApp."]},
 {kop:"Abholung für Ihre Feier in Voorschoten",alineas:["Unser Fischstand steht freitags von 08:00 bis 17:30 auf dem Hoogvliet-Parkplatz in Voorschoten. Möchten Sie dort eine Platte abholen, vereinbaren Sie dies vorher mit uns. Eine Online-Anfrage bedeutet nicht automatisch, dass eine Platte an jedem Ort zu jeder Zeit bereitsteht. Datum, Abholort und Verfügbarkeit müssen gemeinsam bestätigt werden.","Planen Sie einige Tage voraus und melden Sie sich vor stark besuchten Feiertagen früher. Nennen Sie Anlass, Wunschtermin, Personenzahl, Budget und eventuelle Allergien. Gehen Sie nicht von allergenfreier Zubereitung aus: Erklären Sie Ihren Bedarf, damit wir Möglichkeiten und Grenzen besprechen können."]}
 ],questions:[{v:"Kann ich eine Fischplatte für Voorschoten online auswählen?",a:"Ja, Fischplatten können Sie online zusammenstellen. Vereinbaren Sie Datum und Abholort mit uns; Verfügbarkeit und Endpreis werden bestätigt."},{v:"Sieht meine Fischplatte genau wie auf dem Foto aus?",a:"Nein. Das Foto ist ein Beispiel. Größe und Inhalt werden auf Gäste, Budget und Wünsche abgestimmt; Ihre Platte kann größer sein und die Auswahl kann den Preis verändern."},{v:"Kann ich eine Fischplatte freitags bei Hoogvliet abholen?",a:"Fragen Sie vorher an und lassen Sie es von uns bestätigen. Unser Stand steht freitags von 08:00 bis 17:30 bei Hoogvliet in Voorschoten; eine bestimmte Platte wird nach Vereinbarung abgeholt."}]}
 }
};
